<?php

declare(strict_types=1); namespace App\Service\Configurator;
use App\Dto\Configurator\{ConfiguratorConfiguration,ConfiguratorPriceResult,PriceBreakdownLine}; use Sylius\Component\Channel\Model\ChannelInterface; use App\Entity\Configurator\{Configurator,ConfiguratorPriceRule,ConfiguratorValue}; use App\Enum\Configurator\{MultiplierType,PercentageBase,PriceType}; use App\Exception\Configurator\{ConfiguratorNotFoundException,InvalidConfigurationException,MissingPriceRuleException}; use App\Repository\Configurator\{ConfiguratorPriceRuleRepository,ConfiguratorRepository};
final readonly class ConfiguratorPriceCalculator { public function __construct(private ConfiguratorRepository $configurators,private ConfiguratorPriceRuleRepository $rules,private ConfiguratorValidator $validator,private PriceRuleResolver $resolver){} public function calculate(ConfiguratorConfiguration $configuration,ChannelInterface $channel,string $currencyCode):ConfiguratorPriceResult{$model=$this->configurators->findEnabledByCode($configuration->configuratorCode)??throw new ConfiguratorNotFoundException($configuration->configuratorCode);$validation=$this->validator->validate($configuration,$model);if(!$validation->isValid())throw new InvalidConfigurationException(json_encode($validation,JSON_THROW_ON_ERROR));$values=$this->selectedValues($model,$configuration->selections);$ids=array_values(array_filter(array_map(fn($v)=>$v->getId(),$values)));$candidates=$this->rules->findApplicable($model,$ids,$channel,$currencyCode,$configuration->quantity);return $this->calculateRules($configuration,$model,$values,$candidates,$channel->getCode(),$currencyCode);}
 /** @param list<ConfiguratorValue> $values @param iterable<ConfiguratorPriceRule> $rules */ public function calculateRules(ConfiguratorConfiguration $cfg,Configurator $model,array $values,iterable $rules,string $channelCode,string $currency):ConfiguratorPriceResult{$resolved=$this->resolver->resolve($rules,$cfg->quantity,$channelCode,$currency);$hasBase=false;$baseUnit=$optionsUnit=$fixed=$percent=0;$lines=[];$deferred=[];foreach($resolved as $rule){if($rule->getPriceType()===PriceType::PERCENT){$deferred[]=$rule;continue;}$isBase=$rule->getValue()===null;if($isBase&&$rule->getPriceType()===PriceType::UNIT)$hasBase=true;$multiplier=$this->multiplier($rule,$cfg);$amount=$rule->getAmount()*$multiplier;if($rule->getPriceType()===PriceType::UNIT){if($isBase)$baseUnit+=$rule->getAmount();else$optionsUnit+=$rule->getAmount();}else{$fixed+=$amount;}$lines[]=$this->line($rule,$multiplier,$amount); }if(!$hasBase)throw new MissingPriceRuleException('No applicable base UNIT price rule was found.');$unitTotal=($baseUnit+$optionsUnit)*$cfg->quantity;foreach($deferred as $rule){$base=match($rule->getPercentageBase()??PercentageBase::SUBTOTAL){PercentageBase::BASE=>$baseUnit*$cfg->quantity,PercentageBase::OPTIONS=>$optionsUnit*$cfg->quantity,PercentageBase::SUBTOTAL=>$unitTotal+$fixed+$percent};$multiplier=$this->multiplier($rule,$cfg);$amount=self::basisPoints($base,$rule->getAmount())*$multiplier;$percent+=$amount;$lines[]=$this->line($rule,$multiplier,$amount,$base);}return new ConfiguratorPriceResult($cfg->quantity,strtoupper($currency),$baseUnit,$optionsUnit,$baseUnit+$optionsUnit,$unitTotal,$fixed,$percent,$unitTotal+$fixed+$percent,$lines);}
 public static function basisPoints(int $amount,int $basisPoints):int{$product=$amount*$basisPoints;return $product>=0?intdiv($product+5000,10000):-intdiv(-$product+5000,10000);} private function multiplier(ConfiguratorPriceRule $rule,ConfiguratorConfiguration $cfg):int{return match($rule->getMultiplierType()){MultiplierType::NONE=>$rule->getPriceType()===PriceType::UNIT?$cfg->quantity:1,MultiplierType::QUANTITY=>$cfg->quantity,MultiplierType::FIELD_VALUE=>$this->fieldMultiplier($rule,$cfg)};} private function fieldMultiplier(ConfiguratorPriceRule $rule,ConfiguratorConfiguration $cfg):int{$code=$rule->getMultiplierField()?->getCode()??'';$value=$cfg->selections[$code]??null;if(!is_int($value)&&!(is_string($value)&&ctype_digit($value)))throw new InvalidConfigurationException("Multiplier field $code must be a non-negative integer.");return (int)$value;} private function line(ConfiguratorPriceRule $r,int $multiplier,int $amount,?int $base=null):PriceBreakdownLine{$v=$r->getValue();return new PriceBreakdownLine($v?'value':'configurator',$v?->getCode()??$r->getConfigurator()->getCode(),$v?->getField()->getCode(),$v?->getCode(),$r->getChargeCode(),$r->getPriceType()->value,$r->getLabel(),$r->getPriceType()===PriceType::UNIT?$r->getAmount():null,$base,$multiplier,$amount);} /** @param array<string,mixed> $selections @return list<ConfiguratorValue> */ private function selectedValues(Configurator $c,array $selections):array{$result=[];foreach($c->getSections() as $section)foreach($section->getFields() as $field)foreach((array)($selections[$field->getCode()]??[]) as $code)foreach($field->getValues() as $value)if($value->getCode()===$code)$result[]=$value;return $result;}
}
